static uint32_t eb_input(unsigned word,unsigned round)
{ return 0x13579bdfu^(word*0x01030507u)^(round*0xf0e1d2c3u); }
static uint32_t eb_mask(unsigned word)
{
 static const uint32_t masks[4]={0x01020408u,0x10204080u,0xa55a0ff0u,0x55aa33ccu};
 return masks[word%4]^((word/4)*0x11111111u);
}
